@Controller('health/records')
@UseGuards(PatientAuthGuard)
export class HealthRecordController {
  constructor(private readonly prisma: PrismaService) {}

  @Get(':recordId/lab-results')
  async getLabResults(@Param('recordId') recordId: string, @Req() req: RequestWithUser) {
    const record = await this.prisma.healthRecord.findFirst({
      where: { id: recordId, patientId: req.user.patientId },
    });
    if (!record) throw new ForbiddenException('Access denied to requested medical record');
    return await this.prisma.labResult.findMany({
      where: { recordId },
      include: { biomarkers: true, orderingPhysician: true },
    });
  }
}
